/* Cross-record capability checks. Structural validation is generated by Ajv. */
(() => {
  function bounds(schema,value,definitions,context,path='$') {
    if(schema.$ref) return bounds(definitions[schema.$ref.split('/').at(-1)],value,definitions,context,path);
    for(const keyword of ['oneOf','anyOf']) if(schema[keyword]) {
      const branch=schema[keyword].find(b=>b.$ref && CompiledContracts[b.$ref.split('/').at(-1)](value));
      if(branch) bounds(branch,value,definitions,context,path);
    }
    if(schema.type==='object') for(const [key,child] of Object.entries(schema.properties || {})) if(key in value) bounds(child,value[key],definitions,context,`${path}.${key}`);
    if(schema.type==='array') value.forEach((v,i)=>bounds(schema.items,v,definitions,context,`${path}[${i}]`));
    if(schema['x-maximum-from']) {
      let limit=context;
      for(const part of schema['x-maximum-from'].split('.')) {
        if(!limit || !Object.hasOwn(limit,part)) throw new Error(`${path}: unresolved capability`);
        limit=limit[part];
      }
      if(value>limit) throw new Error(`${path}: exceeds system capability ${limit}`);
    }
  }
  globalThis.ContractRuntime={bounds};
})();
